import "google/protobuf/timestamp.proto";
import "google/protobuf/empty.proto";
import "protoc-gen-swagger/options/annotations.proto";

package flipt;

option go_package = ".;flipt";

option (grpc.gateway.protoc_gen_swagger.options.openapiv2_swagger) = {
  info: {
    title: "Flipt API";
    version: "latest";
    contact: {
      name: "Mark Phelps";
      url: "https://github.com/markphelps/flipt";
    };
  };
  external_docs: {
    url: "https://flipt.io";
    description: "Flipt Docs";
  }
  schemes: HTTP;
  schemes: HTTPS;
  consumes: "application/json";
  produces: "application/json";
};

message EvaluationRequest {
  option (grpc.gateway.protoc_gen_swagger.options.openapiv2_schema) = {
    json_schema: {
      required: ["flag_key", "entity_id"]
    }
  };

  string request_id = 1;
  string flag_key = 2;
  string entity_id = 3;
  map<string, string> context = 4;
}

message BatchEvaluationRequest {
  option (grpc.gateway.protoc_gen_swagger.options.openapiv2_schema) = {
    json_schema: {
      required: ["requests"]
    }
  };

  string request_id = 1;
  repeated EvaluationRequest requests = 2;
}

message EvaluationResponse {
  string request_id = 1;
  string entity_id = 2;
  map<string, string> request_context = 3;
  bool match = 4;
  string flag_key = 5;
  string segment_key = 6;
  google.protobuf.Timestamp timestamp = 7;
  string value = 8;
  double request_duration_millis = 9;
}

message BatchEvaluationResponse {
  string request_id = 1;
  repeated EvaluationResponse responses = 2;
  double request_duration_millis = 3;
}

message Flag {
  string key = 1;
  string name = 2;
  string description = 3;
  bool enabled = 4;
  google.protobuf.Timestamp created_at = 5;
  google.protobuf.Timestamp updated_at = 6;
  repeated Variant variants = 7;
}

message FlagList {
  repeated Flag flags = 1;
}

message GetFlagRequest {
  option (grpc.gateway.protoc_gen_swagger.options.openapiv2_schema) = {
    json_schema: {
      required: ["key"]
    }
  };

  string key = 1;
}

message ListFlagRequest {
  int32 limit = 1;
  int32 offset = 2;
}

message CreateFlagRequest {
  option (grpc.gateway.protoc_gen_swagger.options.openapiv2_schema) = {
    json_schema: {
      required: ["key", "name"]
    }
  };

  string key = 1;
  string name = 2;
  string description = 3;
  bool enabled = 4;
}

