 89	func (s *Server) evaluate(ctx context.Context, r *flipt.EvaluationRequest) (*flipt.EvaluationResponse, error) {
 90		var (
 91			ts   = timestamppb.Now()
 92			resp = &flipt.EvaluationResponse{
 93				RequestId:      r.RequestId,
 94				EntityId:       r.EntityId,
 95				RequestContext: r.Context,
 96				Timestamp:      ts,
 97				FlagKey:        r.FlagKey,
 98			}
 99		)
100	
101		flag, err := s.store.GetFlag(ctx, r.FlagKey)
102		if err != nil {
103			return resp, err
104		}
105	
106		if !flag.Enabled {
107			return resp, errors.ErrDisabledf("flag %q is disabled", r.FlagKey)
108		}
109	
110		rules, err := s.store.GetEvaluationRules(ctx, r.FlagKey)
111		if err != nil {
112			return resp, err
113		}
114	
115		if len(rules) == 0 {
116			s.logger.Debug("no rules match")
117			return resp, nil
118		}
119	
120		var lastRank int32
121	
122		// rule loop
123		for _, rule := range rules {
124			if rule.Rank < lastRank {
125				return resp, errors.ErrInvalidf("rule rank: %d detected out of order", rule.Rank)
 52	}
